-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhCN" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.hunter.ranged.Name"] = "远程"
L["rm.era.hunter.ranged.Description"] = "1 至 60 级的所有猎人，所有天赋树。以猎人印记、瞄准射击和自动射击拉怪。单刷时由宠物坦克：你自己的毒蛇钉刺，然后仅在法力值高于一半时使用瞄准射击、奥术射击和多重射击，拥有宠物之前用震荡射击放风筝。组队时，在自动射击之后立即使用瞄准射击和多重射击，确保自动射击绝不被推迟，团队副本之外使用毒蛇钉刺，奥术射击仅在瞄准射击之前或对濒死目标使用。敌人贴得太近时使用近战技能，移动时使用瞬发技能，三个或更多敌人时使用多重射击和乱射。提醒：雄鹰守护（学会前为灵猴守护）、强击光环、宠物照料，对精英和在副本中使用急速射击、狂野怒火和种族技能，胁迫和假死。陷阱、摔绊、喂养宠物、宁神射击和站位由你自己掌控。"
L["rm.era.hunter.ranged.icyveins.Name"] = "远程，截断自动射击（Icy Veins）"
L["rm.era.hunter.ranged.icyveins.Description"] = "默认关闭；如果你的远程武器速度快于 3.0 秒，请启用它。与“猎人：远程”相同，但组队时瞄准射击和多重射击一就绪就施放，即使会推迟自动射击也是如此，从不使用毒蛇钉刺，并且每次拉怪都使用急速射击、狂野怒火和种族技能。"
L["rm.era.hunter.ranged.simulator.Name"] = "远程，团队毒蛇钉刺（模拟器）"
L["rm.era.hunter.ranged.simulator.Description"] = "默认关闭；如果团队的减益效果栏位还能容下你的钉刺，请启用它。与“猎人：远程”相同，但组队时在任何地方都保持毒蛇钉刺，包括团队副本，在瞄准射击和多重射击都在冷却时于剩余不到 5 秒时刷新，并且从不使用奥术射击。"
L["rm.forever.hunter.ranged.Name"] = "远程（Wowhead）"
L["rm.forever.hunter.ranged.Description"] = "适用于 1 至 60 级的所有远程猎人（野兽控制、射击，以及学会陆行鸟踢击之前的生存），也是永久服猎人的默认循环。拉怪：猎人印记、疾速杀戮持续期间使用狙击、自动射击。然后是你自己的毒蛇钉刺，在共用冷却中两次召唤雄鹰和一次奥术射击（学会召唤雄鹰之前奥术射击冷却完毕即用），疾速杀戮期间或对精英使用狙击，瞄准射击。两个或更多敌人与你交战时：用多重射击代替瞄准射击，附近有三个敌人时使用爆炸陷阱，五个时使用乱射。移动时：只使用瞬发射击。近战范围内的怪物会吃到猛禽一击和猫鼬撕咬。提醒：雄鹰守护（学会前为灵猴守护）、强击光环、召唤和复活宠物、急速射击、对精英或在地下城中使用狂野怒火和血性狂暴、怪物贴身时使用胁迫。宠物指令、喂食、放风筝和假死由你自己掌控；如果你使用独来独往，请禁用宠物提醒。它从不读取你的法力值或任何人的生命值，因为永久服对插件隐藏这些数据，所以猎人印记和毒蛇钉刺会施加在每个目标上，治疗宠物由你自己掌控。"
L["rm.forever.hunter.ranged.mobalytics.Name"] = "远程，节省法力（Mobalytics）"
L["rm.forever.hunter.ranged.mobalytics.Description"] = "Mobalytics 的节省法力升级打法，是推荐的 Wowhead 远程内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。保持你自己的毒蛇钉刺，保持一只召唤出的雄鹰，瞄准射击（两个或更多敌人时用多重射击），学会召唤雄鹰后不再使用奥术射击；对血量充足的目标召唤第二只雄鹰这一项被省略了，因为永久服隐藏目标生命值。拉怪、近战、移动和提醒与 Wowhead 内置循环相同。"
L["rm.forever.hunter.survival.Name"] = "生存近战（Wowhead）"
L["rm.forever.hunter.survival.Description"] = "当生存是你的主要天赋树且已点出 21 点（陆行鸟踢击所在层）后的双持近战生存（在此之前按指南建议由远程内置循环带你升级）。以猎人印记和毒蛇钉刺拉怪，然后是猫鼬撕咬、陆行鸟踢击、猛禽一击和反击，三个或更多敌人时使用爆炸陷阱。不在近战范围时进行射击：毒蛇钉刺、奥术射击、瞄准射击、自动射击。提醒：野兽守护、猎人印记（暴露猎物需要它）、对精英或在地下城中使用急速射击和血性狂暴、你持有目标注意力时的威慑、宠物照料（永久服中生命值是隐藏的，因此治疗宠物由你自己掌控）。可选的献祭陷阱步骤默认关闭。"
L["rm.forever.hunter.survival.weave.Name"] = "生存双手穿插（Wowhead）"
L["rm.forever.hunter.survival.weave.Description"] = "Wowhead 针对双手武器生存猎人的进出穿插打法，是推荐的生存近战内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。近战时：猫鼬撕咬和猛禽一击；当猛禽一击还需 2.5 秒以上才就绪时，使用陆行鸟踢击并退出近战。不在近战时：毒蛇钉刺、奥术射击、瞄准射击和自动射击，直到猛禽一击即将就绪，然后回到近战。移动由你来做；RM 会跟随你的距离。"
L["rm.mop.hunter.beastmastery.Name"] = "推荐"
L["rm.mop.hunter.beastmastery.Description"] = "在野兽控制专精中自动选择。以猎人印记和杀戮命令开场，然后：杀戮射击，杀戮命令（狂野怒火即将就绪时稍作保留），点了相应天赋时使用夺命黑鸦、山猫冲锋、凶暴野兽和你的第六层天赋射击，狂乱达到五层（或四层且即将消失）时使用集中火力，但狂野怒火期间不用，对能存活较久的目标使用毒蛇钉刺，用眼镜蛇射击刷新它，集中值达到 80 或狂野怒火期间使用奥术射击，然后是眼镜蛇射击（81 级前为稳固射击）。有两个或更多敌人与你交战时，用多重射击保持野兽顺劈斩，面对大群怪时只在集中值有余时使用杀戮命令，三个起建议使用爆炸陷阱。提醒：召出宠物、复活和治疗宠物、雄鹰守护或铁鹰守护、反制射击、热情，以及在值得的战斗中（精英、地下城或团队副本，或能存活较久的目标）使用狂野怒火、急速射击、群兽奔腾和种族技能。陷阱放置、误导、假死和防御技能由你自己掌控；意气风发和威慑的提醒默认关闭。"
L["rm.mop.hunter.marksmanship.Name"] = "推荐"
L["rm.mop.hunter.marksmanship.Description"] = "在射击专精中自动选择。预读瞄准射击，然后：成对使用稳固射击以保持稳固集中（63 级起），奇美拉射击，对能存活较久的目标使用毒蛇钉刺，开火！让瞄准射击变为瞬发时立即使用，杀戮射击，你的天赋技能，以及在目标生命值高于 80%、急速射击或嗜血期间、集中值达到 85 或奇美拉射击还有几秒就绪时读条施放瞄准射击。奥术射击仅在你移动时使用；否则使用稳固射击。四个或更多敌人时：奇美拉射击、瞬发瞄准射击、多重射击、杀戮射击、爆炸陷阱。提醒与其他猎人内置循环相同。如果你更喜欢把多余的集中值花在奥术射击上，请使用奥术射击版本。"
L["rm.mop.hunter.marksmanship.icyveins.Name"] = "奥术射击泄能（Icy Veins）"
L["rm.mop.hunter.marksmanship.icyveins.Description"] = "作为射击内置循环的替代，按照 Icy Veins、Method、wowtbc.gg 和 Hekili 的打法：瞄准射击仅在目标生命值高于 80% 或急速射击、嗜血期间读条施放，多余的集中值改为在 60 点时用于奥术射击。稳固集中在剩余不到 4 秒时刷新；四个或更多敌人时多重射击优先。默认关闭：启用它并禁用射击内置循环，或提高它的优先级。"
L["rm.mop.hunter.survival.Name"] = "推荐"
L["rm.mop.hunter.survival.Description"] = "在生存专精中自动选择。以猎人印记、黑箭和爆炸射击开场，然后：爆炸射击冷却完毕即用，每次荷枪实弹触发时也使用，杀戮射击，对能存活较久的目标使用黑箭，你的天赋技能，用眼镜蛇射击保持毒蛇钉刺，集中值达到 75、狩猎刺激触发，或黑箭不会很快就绪时于 55 点使用奥术射击，然后是眼镜蛇射击（81 级前为稳固射击）。两个或更多敌人时：荷枪实弹触发且集中值满时优先多重射击，爆炸射击（最多五个目标），杀戮射击，黑箭，三个起使用爆炸陷阱，用多重射击消耗集中值。提醒与其他猎人内置循环相同；为触发荷枪实弹而放置陷阱由你自己掌控。"
L["rm.mop.hunter.unspecialized.Name"] = "选择专精前"
L["rm.mop.hunter.unspecialized.Description"] = "适用于 1 至 9 级以及尚未选择专精的猎人；一旦你选择专精，野兽控制、射击和生存的内置循环就会接管。以猎人印记和奥术射击拉怪，然后对能存活较久的目标使用毒蛇钉刺，三个或更多敌人时使用多重射击，奥术射击、稳固射击和自动射击。会提醒你召唤、复活和治疗宠物，并保持雄鹰守护。"
L["rm.retail.hunter.beastmastery.Name"] = "暴雪战斗辅助"
L["rm.retail.hunter.beastmastery.Description"] = "推荐野兽控制专精使用。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议（它会自行召唤宠物）；你施法或引导时它会等待。同时提醒战斗辅助留给你处理的部分：战斗中的血溅十方和你的种族冷却技能、对可打断的施法使用反制射击，以及战斗中一就绪就使用的优胜劣汰。敌人的施法在战斗中是隐藏的，因此打断提醒只在游戏显示它们的场合亮起；生命值在正式服中是隐藏的，因此何时使用你的防御技能（包括意气风发和灵龟守护）由你自己决定。饰品、误导和宠物照料仍由你自己掌控。"
L["rm.retail.hunter.beastmastery.guide.Name"] = "参考（SimulationCraft 和 Icy Veins）"
L["rm.retail.hunter.beastmastery.guide.Description"] = "仅供参考，默认关闭：优化后的野兽控制优先级。在至暗之夜的战斗中，充能、冷却和触发效果对插件隐藏，因此它无法在战斗中运行；可以阅读它，或复制后自行试验。正式服上集中值是隐藏的。拉怪前召唤宠物并用猎人印记标记目标。狂野怒火即将就绪前或倒刺射击充能将满前使用倒刺射击；狂野怒火；猎群领袖之嚎或自然之友触发时使用杀戮命令，狂野怒火离就绪还早时也可随意使用；眼镜蛇利牙触发时使用眼镜蛇射击；眼镜蛇射击；集中值不足以施放眼镜蛇射击时使用倒刺射击。黑暗游侠：凋零射击期间使用黑蚀箭，凋零射击结束时使用哀恸箭。三个或更多敌人（有野兽顺劈时为两个）：使用狂野鞭笞触发野兽顺劈，然后在其持续期间使用杀戮命令、倒刺射击和眼镜蛇射击。提醒：血溅十方以及战斗辅助内置循环中的功能性提醒。"
L["rm.retail.hunter.initial.Name"] = "暴雪战斗辅助"
L["rm.retail.hunter.initial.Description"] = "推荐在你选择专精之前使用（此时游戏报告的是猎人的初始专精）。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时包含所有猎人内置循环共用的提醒，每一项在你学会对应法术后生效。当你在 10 级选择专精后，该专精的内置循环会接管。"
L["rm.retail.hunter.marksmanship.Name"] = "暴雪战斗辅助"
L["rm.retail.hunter.marksmanship.Description"] = "推荐射击专精使用。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时提醒战斗辅助留给你处理的部分：战斗中的百发百中和你的种族冷却技能、对可打断的施法使用反制射击，以及战斗中一就绪就使用的优胜劣汰。敌人的施法在战斗中是隐藏的，因此打断提醒只在游戏显示它们的场合亮起；生命值在正式服中是隐藏的，因此何时使用你的防御技能（包括意气风发和灵龟守护）由你自己决定。"
L["rm.retail.hunter.marksmanship.guide.Name"] = "参考（SimulationCraft 和 Icy Veins）"
L["rm.retail.hunter.marksmanship.guide.Description"] = "仅供参考，默认关闭：优化后的射击优先级，会在下一次瞄准射击前用掉弹无虚发。触发效果和充能在至暗之夜的战斗中是隐藏的，因此它无法在战斗中运行；正式服上集中值是隐藏的，因此省略了面对成群敌人时 70 集中值的多重射击。标记目标并以瞄准射击开场。哨兵：爆炸射击，乱射，百发百中，在窗口期结束前使用月光战轮，百发百中期间没有弹无虚发时使用瞄准射击，急速射击，夺命射击，弹无虚发触发时使用多重射击（有多头蛇守护时两个敌人即可）或奥术射击，瞄准射击，月光战轮，稳固射击。黑暗游侠：弹无虚发触发时优先使用黑蚀箭，荷枪实弹期间不使用爆炸射击，瞄准射击充能溢出前使用瞄准射击，哀恸箭。三个或更多敌人且有技巧射击时：爆炸射击，乱射，使用多重射击触发技巧射击，百发百中，然后在其持续期间使用急速射击和瞄准射击。为了叠满 30 层正中靶心或面对未标记的目标而使用百发百中的时机仍由你自己掌控。"
L["rm.retail.hunter.survival.Name"] = "暴雪战斗辅助"
L["rm.retail.hunter.survival.Description"] = "推荐生存专精使用。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议（它会自行召唤宠物）；你施法或引导时它会等待。同时提醒战斗辅助留给你处理的部分：战斗中的狩魂一击和你的种族冷却技能、对可打断的施法使用压制，以及战斗中一就绪就使用的优胜劣汰。敌人的施法在战斗中是隐藏的，因此打断提醒只在游戏显示它们的场合亮起；生命值在正式服中是隐藏的，因此何时使用你的防御技能（包括意气风发和灵龟守护）由你自己决定。"
L["rm.retail.hunter.survival.guide.Name"] = "参考（SimulationCraft）"
L["rm.retail.hunter.survival.guide.Description"] = "仅供参考，默认关闭：SimulationCraft 的生存优先级：杀戮命令积累利矛之刃，狩魂一击、爆裂火铳、野火炸弹和猛禽一击消耗它。利矛之刃和充能在至暗之夜的战斗中是隐藏的，因此它无法在战斗中运行。召唤宠物，用猎人印记标记目标，并以野火炸弹开场。哨兵：没有利矛之刃时使用杀戮命令，爆裂火铳，哨兵印记触发时使用野火炸弹，狩魂一击就绪前先使用杀戮命令，狩魂一击，月光战轮，猛禽一击，然后是杀戮命令、野火炸弹和狩魂一击。猎群领袖：猎群领袖之嚎触发时使用杀戮命令，然后在有利矛之刃时使用狩魂一击、野火炸弹、爆裂火铳和猛禽一击。三个或更多敌人时：在狩魂一击之前使用爆裂火铳和野火炸弹，猛禽横扫。提醒：不在近战范围时使用雄鹰守护以及功能性提醒。"
L["rm.sod.hunter.melee.Name"] = "近战（探索赛季）"
L["rm.sod.hunter.melee.Description"] = "在探索赛季服务器上，当你铭刻了侧翼打击、翼龙打击或削凿，且既没有铭刻奇美拉射击也没有铭刻爆炸射击时选用。保持侧翼打击的增益效果，猛禽之怒达到四层时使用猫鼬撕咬，巧思打击触发时使用翼龙打击，每次重置时使用猛禽一击，然后是猫鼬撕咬、翼龙打击、侧翼打击和削凿；献祭陷阱和摔绊仅在空闲时使用。三个或更多敌人时使用削凿和爆炸陷阱；无法接近目标时使用毒蛇钉刺和射击。提醒：猎鹰守护（60 级前为雄鹰守护）、法力值低于 5% 时使用蝰蛇守护、宠物照料（铭刻了独来独往时不提醒）、侧翼打击叠起后使用急速射击和种族技能、狂野怒火。站位和宠物指令由你自己掌控。"
L["rm.sod.hunter.ranged.Name"] = "远程（探索赛季）"
L["rm.sod.hunter.ranged.Description"] = "探索赛季服务器上的所有远程猎人，1 至 60 级；符文铭刻后即会使用。始终保持毒蛇钉刺，并由奇美拉射击刷新。铭刻了夺命射击腿部符文时：技巧射击达到四层时使用多重射击，急速射击期间以及对处于斩杀阶段的目标使用夺命射击，奇美拉射击，然后在多重射击冷却期间使用爆炸陷阱和奥术射击。未铭刻时：奇美拉射击，狙击训练达到两层时（若没有该符文，则紧接自动射击之后）使用瞄准射击，在奇美拉射击即将就绪前放置陷阱（冰霜陷阱仅用于触发荷枪实弹），爆炸射击，稳固射击，多重射击，奥术射击。敌人贴得太近时使用近战技能，移动时使用瞬发技能，三个或更多敌人时使用陷阱、多重射击和乱射。提醒：雄鹰守护、法力值低于 10% 时使用蝰蛇守护、雄狮之心、强击光环、宠物照料（铭刻了独来独往时不提醒）、狂乱达到五层时使用集中火力，对精英和在副本中使用急速射击、种族技能和狂野怒火。铭刻了荷枪实弹时，拉怪前会使用冰霜陷阱。近战穿插和站位由你自己掌控。"
L["rm.tbc.hunter.ranged.simulator.Name"] = "远程 DPS（模拟器）"
L["rm.tbc.hunter.ranged.simulator.Description"] = "1–70 级，所有专精。以猎人印记、瞄准射击和自动射击拉怪，保持自动射击，目标贴近时使用近战攻击。学会稳固射击之前，保持毒蛇钉刺，仅在法力充足时才把法力花在瞄准射击、多重射击和奥术射击上。62 级起：多重射击就绪即用，每次自动射击后立即使用稳固射击，用奥术射击填补空隙，单刷时使用毒蛇钉刺。有三个或更多敌人与你交战时，多重射击就绪即用。会提醒你守护（法力值不足时用蝰蛇守护，法力恢复到一半时换回雄鹰守护）、宠物照料、杀戮命令、对精英和首领使用主要冷却技能，以及沉默射击。宠物指令、误导、陷阱、乱射、近战穿插和假死由你自己掌控。"
L["rm.tbc.hunter.ranged.wowhead.Name"] = "远程 DPS（Wowhead）"
L["rm.tbc.hunter.ranged.wowhead.Description"] = "1–70 级，所有专精，遵循 Wowhead 的团队建议。拉怪、近战、升级阶段的射击、多目标多重射击和提醒都与 模拟器 版本相同，但学会稳固射击后，每次自动射击后只提供多重射击和稳固射击：不用奥术射击填充（移动时除外），不用毒蛇钉刺，也没有蝰蛇守护提醒。宠物指令、误导、陷阱、乱射、近战穿插和假死由你自己掌控。它是推荐的 模拟器 远程内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。"
